using J=ReaderJson;using R=core::Rect;using P=core::Point;
void need(bool b){if(!b)throw std::invalid_argument("Invalid Reader presentation");}
bool contains(R r,P p){return std::isfinite(p.x)&&std::isfinite(p.y)&&p.x>=r.x&&p.y>=r.y&&p.x<r.x+r.width&&p.y<r.y+r.height;}
J box(R r){return J::Array{r.x,r.y,r.width,r.height};}J color(ReaderColor c){return J::Object{{"sRGB",J::Array{c[0],c[1],c[2],c[3]}}};}ReaderColor white(double w,double a=1){return {w,w,w,a};}ReaderColor alpha(ReaderColor c,double a){c[3]=a;return c;}
void validColor(ReaderColor c){for(const auto n:c)need(std::isfinite(n)&&n>=0&&n<=1);}
J layer(std::string id,R r){return J::Object{{"id",std::move(id)},{"kind","layer"},{"bounds",box({0,0,r.width,r.height})},{"position",J::Array{r.x,r.y}},{"anchorPoint",J::Array{0,0}},{"opacity",1},{"children",J::Array{}}};}
J fill(std::string id,R r,ReaderColor c){auto j=layer(std::move(id),r);j["backgroundColor"]=color(c);return j;}
J text(std::string id,std::string value,R r,double size,ReaderColor c,std::string align="natural",bool wrapped=false){auto j=layer(std::move(id),r);j["kind"]="text";j["text"]=J::Object{{"string",std::move(value)},{"fontSize",size},{"font",J::Object{{"familyName",".AppleSystemUIFont"},{"postScriptName",".AppleSystemUIFontDemi"},{"pointSize",size}}},{"foregroundColor",color(c)},{"alignment",std::move(align)},{"wrapped",wrapped},{"truncation","end"},{"runs",J::Array{}}};return j;}
J command(const char*op,std::initializer_list<P>p){J::Array a;for(auto q:p)a.emplace_back(J::Array{q.x,q.y});return J::Object{{"op",op},{"points",std::move(a)}};}
J cut(R r){const auto c=std::min(4.,std::min(r.width,r.height)/3);return J::Array{command("move",{{r.x+c,r.y}}),command("line",{{r.x+r.width,r.y}}),command("line",{{r.x+r.width,r.y+r.height-c}}),command("line",{{r.x+r.width-c,r.y+r.height}}),command("line",{{r.x,r.y+r.height}}),command("line",{{r.x,r.y+c}}),command("close",{})};}
J shape(std::string id,R r,J path,ReaderColor c,bool rim,float opacity){auto j=layer(std::move(id),r);j["kind"]="shape";j["opacity"]=opacity;j["shape"]=J::Object{{"path",std::move(path)},{"fillColor",rim?J{}:color(c)},{"strokeColor",rim?color(c):J{}},{"lineWidth",rim?.9:1},{"lineCap","butt"},{"lineJoin","miter"},{"fillRule","non-zero"}};return j;}
void feedback(ReaderArtwork&out,J::Array&parent,const ReaderAction&a,ReaderColor accent,std::string prefix){auto group=layer(prefix,a.rect);group["allowsGroupOpacity"]=false;group["name"]="hud.control.highlight";const auto tint=prefix+"/tint",rim=prefix+"/rim";group["children"]=J::Array{shape(tint,{0,0,a.rect.width,a.rect.height},cut({0,0,a.rect.width,a.rect.height}),alpha(accent,.30),false,0),shape(rim,{0,0,a.rect.width,a.rect.height},cut({-2,-2,a.rect.width+4,a.rect.height+4}),accent,true,a.enabled?.28f:0.f)};parent.push_back(std::move(group));out.feedback.push_back({a.id,tint,rim,a.rect,a.enabled,a.enabled?.28f:0.f});}
void action(ReaderArtwork&out,J::Array&parent,const ReaderAction&a,ReaderColor ink,ReaderColor accent,std::string prefix,bool menu){parent.push_back(fill(prefix+"/plate",a.rect,a.selected?alpha(accent,.22):alpha(ink,.07)));if(menu&&!a.enabled)parent.back()["opacity"]=.4;
    // Canvas has disabled feedback artwork too; retained menus omit it.
    if(a.enabled||!menu)feedback(out,parent,a,accent,prefix+"/highlight");const auto r=menu?R{a.rect.x+6,a.rect.y+5,a.rect.width-12,a.rect.height-10}:R{a.rect.x+3,a.rect.y+a.rect.height/2-7,a.rect.width-6,14};parent.push_back(text(prefix+"/label",a.label,r,menu?10:11,alpha(ink,a.enabled?1:.3),menu?"natural":"center"));
    // ReaderCanvas's plate is always opaque as a layer; its color alpha alone
    // is .07 even for a disabled action.

}
